// Turn each email into one item per PDF or image attachment, in the binary field "data".
const out = [];
for (const item of $input.all()) {
  for (const [key, file] of Object.entries(item.binary ?? {})) {
    const type = file.mimeType ?? '';
    if (type === 'application/pdf' || type.startsWith('image/')) {
      out.push({
        json: { from: item.json.from?.text ?? '', subject: item.json.subject ?? '', file_name: file.fileName },
        binary: { data: file },
      });
    }
  }
}
return out;

// One row per line item, with the invoice fields repeated on each row.
// Works with any Parser Template: the first list of objects in the result is
// treated as the line items; every plain field becomes a column.
const sourceNames = $('One item per attachment').all().map(f => f.json.file_name);
const rows = [];

$input.all().forEach((item, i) => {
  const data = item.json.data || {};
  const header = { source_file: sourceNames[i] ?? '' };
  let lines = [];
  for (const [key, value] of Object.entries(data)) {
    if (Array.isArray(value) && value.length && typeof value[0] === 'object') {
      if (!lines.length) lines = value;
    } else if (value === null || typeof value !== 'object') {
      header[key] = value;
    }
  }
  header.request_id = item.json.request_id;

  if (!lines.length) {
    rows.push({ json: header });
    return;
  }
  for (const line of lines) {
    const row = { ...header };
    for (const [key, value] of Object.entries(line)) row[`line_${key}`] = value;
    rows.push({ json: row });
  }
});

return rows;
